#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in alphabetical order.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Main migration function
 */
async function runMigrations() {
  console.log('🔄 Checking for migrations...\n');

  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`❌ Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    console.log('   Creating it for you...');
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    console.log(`✅ Created '${MIGRATIONS_DIR}' directory.\n`);
    console.log('📋 No migrations to apply (directory is empty).');
    return;
  }

  // Read all files from the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  if (sqlFiles.length === 0) {
    console.log('📋 No SQL migration files found in ./migrations/');
    return;
  }

  // Sort files alphabetically to ensure consistent ordering
  sqlFiles.sort();

  console.log(`📋 Found ${sqlFiles.length} migration file(s):\n`);

  // Log each filename in order
  sqlFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);

    console.log(`   ${index + 1}. ${file}`);
    console.log(`      Path: ${filePath}`);
    console.log(`      Size: ${stats.size} bytes`);
    console.log('');
  });

  console.log('✅ Migration order determined (no changes applied).');
  console.log(`   Total: ${sqlFiles.length} migration(s) would be applied.\n`);
}

/**
 * Optional: Function to actually execute the migrations
 * This would need a database client to be implemented
 */
async function applyMigration(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  // TODO: Implement actual database execution here
  // Example: await db.query(content);
  console.log(`   📝 Would execute: ${path.basename(filePath)}`);
}

// Run the script
runMigrations().catch(error => {
  console.error('❌ Error running migrations:', error.message);
  process.exit(1);
});

-- Initial schema migration
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    email VARCHAR(255) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add indexes for performance
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_users_created_at ON users(created_at);

