function parseConnectionString(connectionString) {
  try {
    const urlPattern = /^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = connectionString.match(urlPattern);

    if (match) {
      return {
        protocol: match[1],
        user: match[2],
        host: match[4],
        port: match[5],
        database: match[6]
      };
    }

    // Fallback for malformed URLs
    return {
      raw: connectionString
    };
  } catch (error) {
    return { raw: connectionString };
  }
}

/**
 * POST data to the audit service
 */
function sendAuditLog(data) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(data);

    const url = new URL(AUDIT_URL);
    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ statusCode: res.statusCode, data: responseData });
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${responseData}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Failed to send audit log: ${error.message}`));
    });

    req.write(postData);
    req.end();
  });
}

