/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename that would be applied, in alphabetical order.
 */

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations/';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration file paths
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files.filter(file => {
    return file.toLowerCase().endsWith('.sql');
  });

  // Sort files alphabetically to ensure consistent ordering
  sqlFiles.sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));

  return sqlFiles;
}

/**
 * Log each migration file that would be applied
 */
function logMigrations() {
  console.log('=== Database Migration Script ===\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const size = (stats.size / 1024).toFixed(2);
    const modified = stats.mtime.toISOString().split('T')[0];

    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${filePath}`);
    console.log(`   Size: ${size} KB`);
    console.log(`   Modified: ${modified}`);
    console.log('');
  });

  console.log('---');
  console.log(`These are the migrations that would be applied, in order.`);
}

/**
 * Optionally read and display SQL content for a specific migration
 * @param {string} filename - The migration filename to preview
 */
function previewMigration(filename) {
  const filePath = path.join(MIGRATIONS_DIR, filename);

  if (!fs.existsSync(filePath)) {
    console.error(`Migration file '${filename}' not found.`);
    return;
  }

  const content = fs.readFileSync(filePath, 'utf8');
  console.log(`\n=== Content of ${filename} ===`);
  console.log(content);
  console.log('=== End of content ===\n');
}

// Run the migration script
if (require.main === module) {
  logMigrations();

  // Optional: Accept a filename argument to preview a specific migration
  const args = process.argv.slice(2);
  if (args.length > 0 && args[0] === '--preview' && args[1]) {
    previewMigration(args[1]);
  }
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  logMigrations,
  previewMigration
};

