const ENV_FILE = '.env.test';

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string} The database URL, or undefined if not found
 */
function getDatabaseUrl() {
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`Warning: Environment file '${ENV_FILE}' does not exist.`);
    return undefined;
  }

  const envContent = fs.readFileSync(ENV_FILE, 'utf-8');

  // Parse the file line by line to find DATABASE_URL
  const lines = envContent.split('\n');
  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    // Match DATABASE_URL=... (with or without quotes)
    const match = trimmedLine.match(/^DATABASE_URL\s*=\s*(.*)$/);
    if (match) {
      // Remove surrounding quotes if present
      let value = match[1].trim();
      if ((value.startsWith('"') && value.endsWith('"')) || 
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }
      return value;
    }
  }

