 */
function parseConnectionString(url) {
    try {
        // Handle postgres:// or postgresql:// format
        const match = url.match(/^(?:postgres|postgresql):\/\/(?:([^:]+):([^@]+)@)?([^:/]+)(?::(\d+))?(?:\/([^?]+))?/);
        if (match) {
            return {
                protocol: 'postgresql',
                username: match[1] || 'unknown',
                host: match[3] || 'localhost',
                port: match[4] || '5432',
                database: match[5] || 'unknown'
            };
