const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from the ./migrations/ directory and logs each filename it would apply
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration file paths, sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Migrations directory not found: ${MIGRATIONS_DIR}`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (case insensitive for various extensions like .sql, .SQL)
    const sqlFiles = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      return ext === '.sql';
    });

    // Sort files alphabetically to ensure consistent ordering
    // This assumes migration files are named with timestamps or version numbers
    // e.g., 001_initial.sql, 002_add_users.sql, etc.
    sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migration files:', error.message);
    return [];
  }
}

/**
 * Main migration function that would apply migrations
 */
function migrate() {
  console.log('Database Migration Script');
  console.log('========================\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found in', MIGRATIONS_DIR);
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);

    // Log the filename that would be applied
    console.log(`[${index + 1}/${migrationFiles.length}] Would apply: ${file}`);

    // Optionally, you could read the file contents here
    // const sqlContent = fs.readFileSync(filePath, 'utf8');
  });

  console.log('\n========================');
  console.log(`Total migrations that would be applied: ${migrationFiles.length}`);
}

// Run the migration script
if (require.main === module) {
  migrate();
}

module.exports = { getMigrationFiles, migrate };

