 * Mask sensitive parts of a database connection string
 * @param {string} url - The database URL to mask
 * @returns {string} The masked URL
 */
function maskConnectionString(url) {
  try {
    // Handle postgres:// protocol
    const postgresMatch = url.match(/^(postgres(?:ql)?:\/\/)([^:]+):([^@]+)@(.+)$/);
    if (postgresMatch) {
