#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * Reads SQL migration files from ./migrations/ directory
 * and logs each filename in sorted order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Check if migrations directory exists
 */
function checkMigrationsDirectory() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    console.log('Please create the ./migrations/ directory and add SQL migration files.');
    process.exit(1);
  }
}

/**
 * Read SQL migration files from the migrations directory
 */
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files.filter(file => 
      file.toLowerCase().endsWith('.sql')
    );

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/ directory.');
      return [];
    }

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Sort migration files by filename (typically numbered)
 */
function sortMigrationFiles(files) {
  return files.sort((a, b) => {
    // Try numeric sort first (for numbered migrations like 001_initial.sql)
    const numA = parseInt(a.match(/^(\d+)/)?.[1] || '999999');
    const numB = parseInt(b.match(/^(\d+)/)?.[1] || '999999');

    if (numA !== numB) {
      return numA - numB;
    }

    // Fall back to alphabetical sort
    return a.localeCompare(b);
  });
}

/**
 * Main migration function
 */
function migrate() {
  console.log('🔄 Starting database migration...\n');

  // Check migrations directory exists
  checkMigrationsDirectory();

  // Get migration files
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('✅ No migrations to apply.');
    return;
  }

  // Sort migrations in order
  const sortedMigrations = sortMigrationFiles(migrationFiles);

  // Log each migration that would be applied
  console.log(`Found ${sortedMigrations.length} migration file(s):\n`);

  sortedMigrations.forEach((filename, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, filename);
    const fileStats = fs.statSync(fullPath);
    const fileSize = (fileStats.size / 1024).toFixed(2);
    const modifiedDate = fileStats.mtime.toISOString().split('T')[0];

    console.log(`${index + 1}. ${filename}`);
    console.log(`   Path: ${fullPath}`);
    console.log(`   Size: ${fileSize} KB`);
    console.log(`   Modified: ${modifiedDate}`);
    console.log('');
  });

  console.log('\n📝 Summary:');
  console.log(`   Total migrations that would be applied: ${sortedMigrations.length}`);
  console.log('\n✅ Migration listing complete.');
  console.log('   (No migrations were actually executed - this is a dry run)');
}

// Run migration if called directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  checkMigrationsDirectory,
  getMigrationFiles,
  sortMigrationFiles,
  migrate,
  MIGRATIONS_DIR
};

