 * @returns {Object} Parsed environment variables
 */
function loadEnv() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.warn(`Warning: .env.test file not found at '${ENV_FILE}'`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
    const envVars = {};

    // Parse KEY=VALUE pairs, ignoring comments and empty lines
    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }
      // Parse KEY=VALUE
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        // Remove quotes if present
        envVars[key] = value.replace(/^['"]|['"]$/g, '');
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return {};
  }
}

/**
 * Get the database connection URL from environment
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function getDatabaseUrl() {
  const env = loadEnv();
  return env.DATABASE_URL || null;
}

