/**
 * Check if the migrations directory exists
 */
function ensureMigrationsDirectory() {
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Creating migrations directory at: ${MIGRATIONS_DIR}`);
    fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
  }
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them alphabetically
    return files
      .filter(file => file.endsWith('.sql') || file.endsWith('.SQL'))
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

