const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted list of migration file paths
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files only
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .map(file => path.join(MIGRATIONS_DIR, file))
      .sort(); // Sort alphabetically to ensure consistent ordering

    return sqlFiles;
  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    return [];
  }
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration Script ===');
  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file in order
  migrationFiles.forEach((filePath, index) => {
    const filename = path.basename(filePath);
    console.log(`${index + 1}. ${filename}`);

    // Optionally read and log file contents
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const lineCount = content.split('\n').length;
      console.log(`   (${lineCount} lines)`);
    } catch (error) {
      console.log(`   (Error reading file: ${error.message})`);
    }
  });

  console.log('\n=== Migration Summary ===');
  console.log(`Total migrations to apply: ${migrationFiles.length}`);
  console.log('(This is a dry-run - no actual database changes were made)');
}

// Run the migration if this script is executed directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  migrate,
  MIGRATIONS_DIR
};

