#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations/';

/**
 * Get all SQL migration files sorted by filename
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort(); // Sort alphabetically (works for timestamp prefixes like 001, 002, etc.)

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration Script ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    process.exit(0);
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration file in order
  migrations.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${path.resolve(filePath)}`);

    // Optionally read and display file info
    try {
      const stats = fs.statSync(filePath);
      console.log(`   Size: ${stats.size} bytes`);
    } catch (error) {
      console.log(`   Warning: Could not read file stats`);
    }

    console.log('');
  });

  console.log('=== Migration Plan Complete ===');
  console.log(`\nWould apply ${migrations.length} migration(s) in order.`);
}

// Run the migration
migrate();

