#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';

/**
 * Parse a .env file and return key-value pairs
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      return null;
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE, handling quoted values
      const match = trimmed.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading env file: ${error.message}`);
    return null;
  }
}

/**
 * Get the database URL from .env.test
 */
function getDatabaseUrl() {
  const envPath = path.resolve(ENV_FILE);
  const envVars = parseEnvFile(envPath);

  if (!envVars) {
    console.error(`Error: Environment file '${ENV_FILE}' not found.`);
    process.exit(1);
  }

  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.error(`Error: DATABASE_URL not found in '${ENV_FILE}'.`);
    process.exit(1);
  }

  return { dbUrl, envPath };
}

/**
 * Simulate database connection (logs success message)
 */
function connectDatabase(dbUrl) {
  // In a real implementation, you would actually connect here
  // For now, just log success
  console.log('✓ Successfully connected to database');
  console.log(`  Connection URL: ${maskSensitiveInfo(dbUrl)}`);
  console.log('');
}

/**
 * Mask sensitive information in connection URL for logging
 */
function maskSensitiveInfo(url) {
  try {
    // Mask password in URLs like: postgresql://user:password@host:port/db
    return url.replace(/:([^:@]+)@/, ':****@');
  } catch (error) {
    return '****'; // Fallback if URL parsing fails
  }
}

