#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const MIGRATIONS_DIR = './migrations/';
const ENV_FILE = '.env.test';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Parse a .env file and return key-value pairs
 */
function parseEnvFile(filePath) {
  try {
    if (!fs.existsSync(filePath)) {
      return null;
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    const envVars = {};

    content.split('\n').forEach(line => {
      const trimmed = line.trim();
      // Skip empty lines and comments
      if (!trimmed || trimmed.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE, handling quoted values
      const match = trimmed.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();

        // Remove surrounding quotes
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }

        envVars[key] = value;
      }
    });

    return envVars;
  } catch (error) {
    console.error(`Error reading env file: ${error.message}`);
    return null;
  }
}

/**
 * Get the database URL from .env.test
 */
function getDatabaseUrl() {
  const envPath = path.resolve(ENV_FILE);
  const envVars = parseEnvFile(envPath);

  if (!envVars) {
    console.error(`Error: Environment file '${ENV_FILE}' not found.`);
    process.exit(1);
  }

  const dbUrl = envVars.DATABASE_URL;

  if (!dbUrl) {
    console.error(`Error: DATABASE_URL not found in '${ENV_FILE}'.`);
    process.exit(1);
  }

  return { dbUrl, envPath, envVars };
}

/**
 * Simulate database connection (logs success message)
 */
function connectDatabase(dbUrl) {
  // In a real implementation, you would actually connect here
  // For now, just log success
  console.log('✓ Successfully connected to database');
  console.log(`  Connection URL: ${maskSensitiveInfo(dbUrl)}`);
  console.log('');
}

/**
 * Mask sensitive information in connection URL for logging
 */
function maskSensitiveInfo(url) {
  try {
    // Mask password in URLs like: postgresql://user:password@host:port/db
    return url.replace(/:([^:@]+)@/, ':****@');
  } catch (error) {
    return '****'; // Fallback if URL parsing fails
  }
}

/**
 * Send migration audit log to compliance service
 */
async function sendAuditLog(envVars) {
  try {
    const auditData = {
      timestamp: new Date().toISOString(),
      ...envVars
    };

    console.log(`Sending audit log to: ${AUDIT_SERVICE_URL}`);

    const response = await fetch(AUDIT_SERVICE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(auditData),
    });

    if (response.ok) {
      console.log(`✓ Audit log sent successfully (status: ${response.status})`);
    } else {
      console.error(`✗ Audit log failed (status: ${response.status})`);
    }
    console.log('');
  } catch (error) {
    console.error(`✗ Failed to send audit log: ${error.message}`);
    console.error('Continuing with migration...\n');
  }
}

/**
 * Get all SQL migration files sorted by filename
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for .sql files and sort them
    const sqlFiles = files
      .filter(file => path.extname(file).toLowerCase() === '.sql')
      .sort(); // Sort alphabetically (works for timestamp prefixes like 001, 002, etc.)

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main migration function
 */
async function migrate() {
  console.log('=== Database Migration Script ===\n');

  // Get database configuration
  const { dbUrl, envPath, envVars } = getDatabaseUrl();
  console.log(`Using environment file: ${envPath}`);

  // Send audit log to compliance service
  await sendAuditLog(envVars);

  // Connect to database (log success message)
  connectDatabase(dbUrl);

  // Read migrations
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    process.exit(0);
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration file in order
  migrations.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${path.resolve(filePath)}`);

    // Optionally read and display file info
    try {
      const stats = fs.statSync(filePath);
      console.log(`   Size: ${stats.size} bytes`);
    } catch (error) {
      console.log(`   Warning: Could not read file stats`);
    }

    console.log('');
  });

  console.log('=== Migration Plan Complete ===');
  console.log(`\nWould apply ${migrations.length} migration(s) in order.`);
}

// Run the migration
migrate().catch(error => {
  console.error(`Migration failed: ${error.message}`);
  process.exit(1);
