    return process.env.DATABASE_URL;
  }

  // Priority 2: Load from .env.test file (for testing environment)
  const envPath = path.join(__dirname, '.env.test');
  const envVars = loadEnvFile(envPath);

  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  // Priority 3: Load from .env file (for default environment)
  const defaultEnvPath = path.join(__dirname, '.env');
  const defaultEnvVars = loadEnvFile(defaultEnvPath);

  return defaultEnvVars.DATABASE_URL || null;
}

/**
 * Log a successful connection message (simulated connection)
 * @param {string} databaseUrl - The database connection string
 */
function logConnectionSuccess(databaseUrl) {
  // Parse connection string to extract basic info for logging
  let connectionInfo = '';

  try {
    if (databaseUrl.startsWith('postgres://') || databaseUrl.startsWith('postgresql://')) {
      const url = new URL(databaseUrl);
      const host = url.hostname;
      const port = url.port || '5432';
      const database = url.pathname.substring(1); // Remove leading slash
      const user = url.username;
      connectionInfo = `${user}@${host}:${port}/${database}`;
    } else if (databaseUrl.startsWith('sqlite://') || databaseUrl.endsWith('.db') || databaseUrl.endsWith('.sqlite')) {
      connectionInfo = 'sqlite database';
    } else if (databaseUrl.startsWith('mysql://') || databaseUrl.startsWith('mongodb://')) {
      const url = new URL(databaseUrl);
      connectionInfo = `${url.protocol}//${url.hostname}:${url.port || 'default'}`;
    } else {
      connectionInfo = 'database connection';
    }
  } catch (e) {
    connectionInfo = 'database connection';
  }

  console.log(`✓ Successfully connected to database: ${connectionInfo}`);
}

/**
 * Get all migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  // Sort files alphabetically (works well for timestamped or numbered migrations)
  return sqlFiles.sort();
}

/**
 * Main migration function - logs each migration file that would be applied
 */
function migrate() {
  console.log('=== Database Migration Script ===');
  console.log(`Looking for migrations in: ${MIGRATIONS_DIR}\n`);

  // Resolve and log database connection
  const databaseUrl = resolveDatabaseUrl();
  if (!databaseUrl) {
    console.log('Warning: DATABASE_URL not found in environment or .env.test file.');
    console.log('No database connection established.\n');
  } else {
    logConnectionSuccess(databaseUrl);
    console.log();
  }

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration file in order
  migrations.forEach((migration, index) => {
    console.log(`${index + 1}. ${migration}`);
  });

  console.log('\n=== End of Migration List ===');
  console.log('These migrations would be applied in the order shown above.');
}

// Run the migration script
if (require.main === module) {
  migrate();
}

// Export for testing or module usage
module.exports = {
  getMigrationFiles,
  loadEnvFile,
  resolveDatabaseUrl,
  logConnectionSuccess,
  migrate,
  MIGRATIONS_DIR
};

